def unique_subsets(nums):
    """
    Returns all unique sorted subsets of nums, sorted by length then lexicographically.

    Args:
        nums (list): A list of integers.

    Returns:
        list: A list of lists, where each inner list is a unique sorted subset.
    """
    if not nums:
        return [[]]

    # Sort the list to handle duplicates and ensure consistent ordering
    nums_sorted = sorted(nums)

    # Use recursion to generate subsets
    result = []

    def backtrack(current_subset):
        # Base case: if we have a subset, add it to result
        if len(current_subset) == len(nums_sorted):
            result.append(current_subset)
            return

        # Try adding each element from the sorted list
        for i in range(len(nums_sorted)):
            if i > 0 and nums_sorted[i] == nums_sorted[i - 1]:
                # Skip duplicates to avoid generating identical subsets
                continue

            # Recursively build the subset
            backtrack(current_subset + [nums_sorted[i]])

    backtrack([])

    return result
