    min_coins = [0] * (amount + 1)
    min_coins[0] = 0

    # Iterate through each coin denomination
    for coin in coins:
        # For each amount from coin to amount, we can either use 0 coins or 1 coin
        for i in range(coin, amount + 1):
            if i <= min_coins[i - 1]:
                min_coins[i] = min_coins[i - 1] + 1
            else:
                min_coins[i] = 1

    return min_coins[amount]
