def can_finish_courses(num_courses, prereqs):
    """
    Determine if all courses can be completed given a list of prerequisite pairs.

    Args:
        num_courses (int): Number of courses, labeled 0 to num_courses-1.
        prereqs (list of list of int): List of prerequisite pairs (course, prereq).

    Returns:
        bool: True if all courses can be completed, False otherwise.
    """
    # Build adjacency list: prereqs[i] contains the courses that course i depends on
    graph = [[] for _ in range(num_courses)]
    for course, prereq in prereqs:
        graph[prereq].append(course)

    # Kahn's algorithm for topological sort
    # Initialize queue with courses that have no prerequisites
    queue = [i for i in range(num_courses) if not graph[i]]
    visited = [False] * num_courses
    count = 0

    while queue:
        # Process all courses with no prerequisites
        for _ in range(len(queue)):
            course = queue.pop(0)
            visited[course] = True
            count += 1
            # If this course has no prerequisites, add it to queue
            if not graph[course]:
                queue.append(course)

    # If we successfully processed all courses, all are finishable
    return count == num_courses
