    Counts the number of 4-connected islands of '1's in a 2D grid.

    Parameters:
    grid (list of list of str): 2D grid containing '1's and '0's.

    Returns:
    int: Number of connected '1's.
    """
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Initialize a set to store island coordinates
    island_coords = set()

    # Directions for 4-connectivity: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                # Start a new island
                island_coords.add((r, c))
                # BFS/DFS to find all connected '1's
                stack = [(r, c)]
                while stack:
                    r, c = stack.pop()
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                            stack.append((nr, nc))

    return len(island_coords)
