def is_bipartite(adj):
    """
    Check if the given undirected graph is 2-colorable.

    Parameters:
    adj (list of lists): Adjacency list of the graph

    Returns:
    bool: True if the graph is bipartite, False otherwise
    """
    if not adj:
        return True

    # Create a set to store visited nodes
    visited = set()
    # Create a set to store colors (0 for unvisited, 1 for colored)
    colors = set()

    # Iterate through each node
    for u in adj:
        if u not in colors:
            # Start a new color assignment for this node
            colors.add(0)
            # Mark all neighbors as colored
            for v in adj[u]:
                if v not in colors:
                    colors.add(1)
                    # Mark the neighbor as colored
                    colors.add(0)
                    # Mark the neighbor as unvisited
                    visited.add(v)

    # Check if all nodes are colored
    for u in adj:
        if u not in colors:
            return False

    return True
