def canonicalize_unix_path(path):
    """
    Canonicalize an absolute Unix path by resolving ., .., and multiple slashes.
    Returns the canonical path string.
    """
    if not path:
        return ""

    # Normalize the path by resolving . and .. components
    normalized = path
    while normalized.count("..") > 0:
        normalized = normalized.replace("..", "..")

    # Remove trailing slashes and normalize to single slash
    normalized = normalized.rstrip("/")
    if normalized.endswith("/"):
